-- Comprehensive test dataset for jdk_clean.
-- Generated by actually running every scenario through the real
-- application service layer (not hand-typed SQL), then dumping the
-- resulting rows -- every total, discount figure, and status
-- combination here is exactly what the real app produced, not a guess.
--
-- Covers: full happy-path order (feasibility -> auto-quotation ->
-- order -> auto-scheduled production -> auto-created delivery note ->
-- delivered), an order+deal cancelled mid-flight, a raw-material
-- shortfall requiring Sales override, a product with no BOM
-- configured (bom_missing), leftover finished-goods stock recognized
-- by a later feasibility check (covered_by_stock), a quotation and a
-- purchase order each awaiting admin approval (large discount / large
-- amount), a real MRP shortage auto-drafting a purchase order, and
-- overdue orders/POs/feasibility checks flagged for admin review.
--
-- Assumes backend/schema.sql (and all migrations) has already been
-- applied. Every table this file touches is TRUNCATEd before inserting,
-- so this is safe to re-run even against a database that already has
-- data in these specific tables -- it will be replaced, not duplicated
-- or collided with. Tables this file doesn't reference are left alone.

-- Login as any of these once loaded (all use the same password):
--   demo_admin       / Demo@12345   (role: admin)
--   demo_manager     / Demo@12345   (role: manager)
--   demo_sales       / Demo@12345   (role: staff, department: sales)
--   demo_procurement / Demo@12345   (role: staff, department: procurement)
--   demo_warehouse   / Demo@12345   (role: staff, department: warehouse)
-- Change these passwords once you're done testing.

SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

-- Children first, then parents (order doesn't matter with checks off, but
-- keeping it FK-safe means this also works if checks are ever left on).
-- Safe to re-run: everything below is truncated before insert, same as
-- running this against a genuinely fresh database.
TRUNCATE TABLE quotation_details;
TRUNCATE TABLE quotations;
TRUNCATE TABLE order_details;
TRUNCATE TABLE orders;
TRUNCATE TABLE delivery_note_lines;
TRUNCATE TABLE delivery_notes;
TRUNCATE TABLE purchase_order_lines;
TRUNCATE TABLE purchase_orders;
TRUNCATE TABLE production_schedules;
TRUNCATE TABLE feasibility_lines;
TRUNCATE TABLE feasibility_checks;
TRUNCATE TABLE deals;
TRUNCATE TABLE bom_lines;
TRUNCATE TABLE supplier_materials;
TRUNCATE TABLE finished_goods_inventory;
TRUNCATE TABLE raw_material_inventory;
TRUNCATE TABLE stock_movements;
TRUNCATE TABLE products;
TRUNCATE TABLE machines;
TRUNCATE TABLE raw_materials;
TRUNCATE TABLE suppliers;
TRUNCATE TABLE customers;
TRUNCATE TABLE refresh_tokens;
TRUNCATE TABLE audit_log;
TRUNCATE TABLE users;
TRUNCATE TABLE settings;


